from enum import Enum
from typing import Annotated, TypeAlias

from ...core import open_enum_validator


class View9(str, Enum):
    """The initial privacy of the videos generated by streaming to the event as well as the embed privacy of the entire
    collection.

    Option descriptions:
     * ``anybody`` - Anyone can access the event. This privacy setting appears as ``Public`` on the Vimeo front end.
     * ``embed_only`` - The event doesn't appear on Vimeo, but it can be embedded on other sites.
     * ``nobody`` - No one except the owner can access the event. This privacy setting appears as ``Private`` on the
            Vimeo front end.
     * ``password`` - Only those with the password can access the event.
     * ``team`` - Anyone on this team can access the event. This privacy setting appears as ``Company only`` on the
            Vimeo front end.
     * ``unlisted`` - Only those with the private link can access the event."""

    ANYBODY = "anybody"
    EMBED_ONLY = "embed_only"
    NOBODY = "nobody"
    PASSWORD = "password"
    TEAM = "team"
    UNLISTED = "unlisted"

    __str__ = str.__str__


View9OrStr: TypeAlias = Annotated[View9 | str, open_enum_validator(View9)]
